const tok = event.data.token; if (!tok || !event.user?.isSelf) return;
const gm = ChatMessage.getWhisperRecipients("GM").map(u => u.id);
ChatMessage.create({ content: `<b>${tok.name}</b> $у западного выхода из блока: дальше «Пост охраны».`, whisper: gm, speaker: { alias: "Непреклонный" } });

